export default (async () => {
describe('With Setup/Teardown', () => {
  let testData: string[];

  beforeEach(() => {
    testData = ['a', 'b', 'c'];
  });

  afterEach(() => {
    testData = [];
  });

  it('has initial data', () => {
    expect(testData).toHaveLength(3);
  });

  it('can modify data', () => {
    testData.push('d');
    expect(testData).toHaveLength(4);
  });
});

})();